// Avatars for the fictional cast, generated by the dev server so mocks never load images from GitHub.

export const AVATAR_PATH = '/__dev/avatar/';

const HUE_STEPS = 360;

export function avatarUrl(login: string): string {
  return AVATAR_PATH + encodeURIComponent(login) + '.svg';
}

// A URL under the avatar path that the server answers with 404, for the broken-avatar corner case.
export function missingAvatarUrl(login: string): string {
  return AVATAR_PATH + 'missing/' + encodeURIComponent(login) + '.png';
}

function escapeXml(text: string): string {
  return text.replace(/[<>&"']/g, (c) => '&#' + c.charCodeAt(0) + ';');
}

// The same login always gets the same color and initials.
export function avatarSvg(login: string): string {
  let hash = 0;
  for (const char of login) hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
  const parts = login.split(/[-_.]+/).filter(Boolean);
  const initials = (parts.length > 1 ? parts[0][0] + parts[1][0] : login.slice(0, 2)).toUpperCase();
  return '<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 48 48">'
    + '<rect width="48" height="48" fill="hsl(' + (hash % HUE_STEPS) + ' 45% 55%)"/>'
    + '<text x="24" y="30" font-family="sans-serif" font-size="18" font-weight="600" fill="#fff" text-anchor="middle">'
    + escapeXml(initials) + '</text></svg>';
}
